package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class BackChannelLogoutUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property back channel logout uri of trusted client ")
  void test_back_channel_logout_uri_v_o_builder() {
    Assertions.assertFalse(BackChannelLogoutUriVO.nullValue().getBackChannelLogoutUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        BackChannelLogoutUriVO.tryFrom(null).getBackChannelLogoutUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        BackChannelLogoutUriVO.from("one").getBackChannelLogoutUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> BackChannelLogoutUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", BackChannelLogoutUriVO.from("one").toString());
  }
}
